import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";
import * as random from "@pulumi/random";

export interface AppPlatformArgs {
    /** "dev" | "prod" — drives all sizing/hardening decisions. */
    environment: pulumi.Input<string>;

    /** RDS */
    dbInstanceClass: pulumi.Input<string>;
    dbMultiAz: pulumi.Input<boolean>;
    dbStorageEncrypted: pulumi.Input<boolean>;
    dbAllocatedStorage?: pulumi.Input<number>;
    dbBackupRetentionDays?: pulumi.Input<number>;
    dbName?: pulumi.Input<string>;
    dbUsername?: pulumi.Input<string>;
    /** Optional: pass a config secret. If omitted, a random password is generated. */
    dbPassword?: pulumi.Input<string>;

    /** Networking */
    vpcId: pulumi.Input<string>;
    /** Private subnets only — RDS is never publicly accessible. */
    privateSubnetIds: pulumi.Input<pulumi.Input<string>[]>;
    /** CIDRs allowed to reach 5432 (e.g. the EKS node CIDRs). */
    dbIngressCidrs: pulumi.Input<pulumi.Input<string>[]>;

    /** S3 */
    /** Set on prod to enable cross-region replication (e.g. "us-west-2"). */
    replicaRegion?: string;

    /** IAM: OIDC provider ARN + URL of the EKS cluster (IRSA trust). */
    oidcProviderArn: pulumi.Input<string>;
    oidcProviderUrl: pulumi.Input<string>;
    serviceAccountNamespace?: string;
    serviceAccountName?: string;

    tags?: Record<string, string>;
}

/**
 * AppPlatform: one logical unit of "stateful backing services" for the app —
 * an assets bucket, a Postgres instance, and the IRSA role the pods assume.
 */
export class AppPlatform extends pulumi.ComponentResource {
    public readonly bucketName: pulumi.Output<string>;
    public readonly bucketArn: pulumi.Output<string>;
    public readonly dbEndpoint: pulumi.Output<string>;
    public readonly dbPort: pulumi.Output<number>;
    public readonly roleArn: pulumi.Output<string>;
    public readonly connectionSecretArn: pulumi.Output<string>;
    /** Marked secret; never printed to plain stack output unless --show-secrets. */
    public readonly connectionString: pulumi.Output<string>;

    constructor(name: string, args: AppPlatformArgs, opts?: pulumi.ComponentResourceOptions) {
        super("acme:app:AppPlatform", name, {}, opts);
        const parent = { parent: this };

        const isProd = pulumi.output(args.environment).apply(e => e === "prod");
        const tags = { ...(args.tags ?? {}), Environment: pulumi.output(args.environment) as any, ManagedBy: "pulumi" };

        // ---------------------------------------------------------------
        // 1. S3 assets bucket — versioned, encrypted, fully private.
        // ---------------------------------------------------------------
        const bucket = new aws.s3.BucketV2(`${name}-assets`, {
            forceDestroy: false,
            tags,
        }, parent);

        new aws.s3.BucketVersioningV2(`${name}-assets-versioning`, {
            bucket: bucket.id,
            versioningConfiguration: { status: "Enabled" },
        }, parent);

        new aws.s3.BucketServerSideEncryptionConfigurationV2(`${name}-assets-sse`, {
            bucket: bucket.id,
            rules: [{
                applyServerSideEncryptionByDefault: { sseAlgorithm: "AES256" },
                bucketKeyEnabled: true,
            }],
        }, parent);

        new aws.s3.BucketPublicAccessBlock(`${name}-assets-pab`, {
            bucket: bucket.id,
            blockPublicAcls: true,
            blockPublicPolicy: true,
            ignorePublicAcls: true,
            restrictPublicBuckets: true,
        }, parent);

        new aws.s3.BucketOwnershipControls(`${name}-assets-ownership`, {
            bucket: bucket.id,
            rule: { objectOwnership: "BucketOwnerEnforced" },
        }, parent);

        // Deny any non-TLS access.
        new aws.s3.BucketPolicy(`${name}-assets-tls-only`, {
            bucket: bucket.id,
            policy: bucket.arn.apply(arn => JSON.stringify({
                Version: "2012-10-17",
                Statement: [{
                    Sid: "DenyInsecureTransport",
                    Effect: "Deny",
                    Principal: "*",
                    Action: "s3:*",
                    Resource: [arn, `${arn}/*`],
                    Condition: { Bool: { "aws:SecureTransport": "false" } },
                }],
            })),
        }, parent);

        // --- Cross-region replication (prod only) ---
        if (args.replicaRegion) {
            const replicaProvider = new aws.Provider(`${name}-replica-provider`, {
                region: args.replicaRegion as aws.Region,
            }, parent);

            const replicaBucket = new aws.s3.BucketV2(`${name}-assets-replica`, { tags },
                { parent: this, provider: replicaProvider });

            new aws.s3.BucketVersioningV2(`${name}-assets-replica-versioning`, {
                bucket: replicaBucket.id,
                versioningConfiguration: { status: "Enabled" },
            }, { parent: this, provider: replicaProvider });

            new aws.s3.BucketServerSideEncryptionConfigurationV2(`${name}-assets-replica-sse`, {
                bucket: replicaBucket.id,
                rules: [{ applyServerSideEncryptionByDefault: { sseAlgorithm: "AES256" } }],
            }, { parent: this, provider: replicaProvider });

            new aws.s3.BucketPublicAccessBlock(`${name}-assets-replica-pab`, {
                bucket: replicaBucket.id,
                blockPublicAcls: true, blockPublicPolicy: true,
                ignorePublicAcls: true, restrictPublicBuckets: true,
            }, { parent: this, provider: replicaProvider });

            const replRole = new aws.iam.Role(`${name}-replication`, {
                assumeRolePolicy: JSON.stringify({
                    Version: "2012-10-17",
                    Statement: [{
                        Effect: "Allow",
                        Principal: { Service: "s3.amazonaws.com" },
                        Action: "sts:AssumeRole",
                    }],
                }),
                tags,
            }, parent);

            new aws.iam.RolePolicy(`${name}-replication-policy`, {
                role: replRole.id,
                policy: pulumi.all([bucket.arn, replicaBucket.arn]).apply(([src, dst]) => JSON.stringify({
                    Version: "2012-10-17",
                    Statement: [
                        {
                            Effect: "Allow",
                            Action: ["s3:GetReplicationConfiguration", "s3:ListBucket"],
                            Resource: src,
                        },
                        {
                            Effect: "Allow",
                            Action: [
                                "s3:GetObjectVersionForReplication",
                                "s3:GetObjectVersionAcl",
                                "s3:GetObjectVersionTagging",
                            ],
                            Resource: `${src}/*`,
                        },
                        {
                            Effect: "Allow",
                            Action: [
                                "s3:ReplicateObject",
                                "s3:ReplicateDelete",
                                "s3:ReplicateTags",
                            ],
                            Resource: `${dst}/*`,
                        },
                    ],
                })),
            }, parent);

            new aws.s3.BucketReplicationConfig(`${name}-assets-replication`, {
                role: replRole.arn,
                bucket: bucket.id,
                rules: [{
                    id: "replicate-all",
                    status: "Enabled",
                    filter: {},
                    deleteMarkerReplication: { status: "Enabled" },
                    destination: { bucket: replicaBucket.arn, storageClass: "STANDARD_IA" },
                }],
            }, parent);
        }

        // ---------------------------------------------------------------
        // 2. RDS PostgreSQL
        // ---------------------------------------------------------------
        const dbSg = new aws.ec2.SecurityGroup(`${name}-db-sg`, {
            vpcId: args.vpcId,
            description: "Postgres access from cluster nodes only",
            ingress: [{
                protocol: "tcp",
                fromPort: 5432,
                toPort: 5432,
                cidrBlocks: args.dbIngressCidrs,
                description: "postgres",
            }],
            egress: [{ protocol: "-1", fromPort: 0, toPort: 0, cidrBlocks: ["0.0.0.0/0"] }],
            tags,
        }, parent);

        const subnetGroup = new aws.rds.SubnetGroup(`${name}-db-subnets`, {
            subnetIds: args.privateSubnetIds,
            tags,
        }, parent);

        const generated = new random.RandomPassword(`${name}-db-password`, {
            length: 32,
            special: true,
            overrideSpecial: "!#$%*()-_=+[]{}<>:?",
        }, parent);

        const password = pulumi.secret(
            args.dbPassword !== undefined
                ? pulumi.output(args.dbPassword)
                : generated.result,
        );

        const dbUsername = args.dbUsername ?? "appuser";
        const dbName = args.dbName ?? "appdb";

        const db = new aws.rds.Instance(`${name}-db`, {
            engine: "postgres",
            engineVersion: "16.3",
            instanceClass: args.dbInstanceClass,
            allocatedStorage: args.dbAllocatedStorage ?? 20,
            storageType: "gp3",
            storageEncrypted: args.dbStorageEncrypted,
            multiAz: args.dbMultiAz,

            dbName,
            username: dbUsername,
            password,

            dbSubnetGroupName: subnetGroup.name,
            vpcSecurityGroupIds: [dbSg.id],
            publiclyAccessible: false,               // AC #2

            deletionProtection: true,                // AC #2
            backupRetentionPeriod: args.dbBackupRetentionDays ?? 14,   // AC #2 (>= 7)
            backupWindow: "03:00-04:00",
            maintenanceWindow: "Mon:04:30-Mon:05:30",
            copyTagsToSnapshot: true,

            skipFinalSnapshot: false,
            finalSnapshotIdentifier: pulumi.interpolate`${name}-final-${args.environment}`,
            performanceInsightsEnabled: isProd,
            autoMinorVersionUpgrade: true,
            applyImmediately: false,
            tags,
        }, { parent: this, protect: true });

        const connectionString = pulumi.secret(
            pulumi.interpolate`postgresql://${dbUsername}:${password}@${db.endpoint}/${dbName}?sslmode=require`,
        );

        // Store connection string in Secrets Manager (encrypted at rest).
        // Pulumi state also keeps it encrypted via the stack's secrets provider. (AC #3)
        const secret = new aws.secretsmanager.Secret(`${name}-db-conn`, {
            description: "Postgres connection string",
            recoveryWindowInDays: 7,
            tags,
        }, parent);

        new aws.secretsmanager.SecretVersion(`${name}-db-conn-v`, {
            secretId: secret.id,
            secretString: connectionString,
        }, parent);

        // ---------------------------------------------------------------
        // 3. IRSA role for the service account
        // ---------------------------------------------------------------
        const ns = args.serviceAccountNamespace ?? "default";
        const sa = args.serviceAccountName ?? name;

        const role = new aws.iam.Role(`${name}-irsa`, {
            assumeRolePolicy: pulumi.all([args.oidcProviderArn, args.oidcProviderUrl])
                .apply(([providerArn, providerUrl]) => {
                    const host = providerUrl.replace(/^https:\/\//, "");
                    return JSON.stringify({
                        Version: "2012-10-17",
                        Statement: [{
                            Effect: "Allow",
                            Principal: { Federated: providerArn },
                            Action: "sts:AssumeRoleWithWebIdentity",
                            Condition: {
                                StringEquals: {
                                    [`${host}:sub`]: `system:serviceaccount:${ns}:${sa}`,
                                    [`${host}:aud`]: "sts.amazonaws.com",
                                },
                            },
                        }],
                    });
                }),
            tags,
        }, parent);

        // Least privilege: explicit actions, resource-scoped, no wildcards. (AC #4)
        new aws.iam.RolePolicy(`${name}-irsa-policy`, {
            role: role.id,
            policy: pulumi.all([bucket.arn, secret.arn]).apply(([bucketArn, secretArn]) => JSON.stringify({
                Version: "2012-10-17",
                Statement: [
                    {
                        Sid: "ListAssetsBucket",
                        Effect: "Allow",
                        Action: ["s3:ListBucket", "s3:GetBucketLocation"],
                        Resource: bucketArn,
                    },
                    {
                        Sid: "ReadWriteAssets",
                        Effect: "Allow",
                        Action: ["s3:GetObject", "s3:PutObject", "s3:DeleteObject", "s3:GetObjectVersion"],
                        Resource: `${bucketArn}/*`,
                    },
                    {
                        Sid: "ReadDbConnectionSecret",
                        Effect: "Allow",
                        Action: ["secretsmanager:GetSecretValue", "secretsmanager:DescribeSecret"],
                        Resource: secretArn,
                    },
                ],
            })),
        }, parent);

        this.bucketName = bucket.id;
        this.bucketArn = bucket.arn;
        this.dbEndpoint = db.address;
        this.dbPort = db.port;
        this.roleArn = role.arn;
        this.connectionSecretArn = secret.arn;
        this.connectionString = connectionString;

        this.registerOutputs({
            bucketName: this.bucketName,
            dbEndpoint: this.dbEndpoint,
            roleArn: this.roleArn,
            connectionSecretArn: this.connectionSecretArn,
        });
    }
}
