## `index.ts`

```ts
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";
import * as awsx from "@pulumi/awsx";
import * as eks from "@pulumi/eks";
import { AppPlatform } from "./components/appPlatform";

const cfg = new pulumi.Config();
const env = pulumi.getStack();                       // "dev" | "prod"
const isProd = env === "prod";

const nodeCount     = cfg.requireNumber("nodeCount");
const nodeType      = cfg.require("nodeInstanceType");
const dbClass       = cfg.require("dbInstanceClass");
const replicaRegion = cfg.get("replicaRegion");       // set only in prod.yaml
// Secret: `pulumi config set --secret dbPassword ...` (stored encrypted in Pulumi.<stack>.yaml)
const dbPassword    = cfg.getSecret("dbPassword");

const tags = { Environment: env, Project: pulumi.getProject() };

// --- Network ---
const vpc = new awsx.ec2.Vpc(`app-${env}`, {
    cidrBlock: "10.0.0.0/16",
    numberOfAvailabilityZones: isProd ? 3 : 2,
    natGateways: { strategy: isProd ? "OnePerAz" : "Single" },
    tags,
});

// --- EKS cluster with managed node group (AC #5) ---
const cluster = new eks.Cluster(`app-${env}`, {
    vpcId: vpc.vpcId,
    publicSubnetIds: vpc.publicSubnetIds,
    privateSubnetIds: vpc.privateSubnetIds,
    nodeAssociatePublicIpAddress: false,
    createOidcProvider: true,
    skipDefaultNodeGroup: true,
    tags,
});

new eks.ManagedNodeGroup(`app-${env}-ng`, {
    cluster,
    instanceTypes: [nodeType],
    scalingConfig: { desiredSize: nodeCount, minSize: nodeCount, maxSize: nodeCount + 2 },
    subnetIds: vpc.privateSubnetIds,
    nodeRole: cluster.instanceRoles[0],
    tags,
});

// --- The component ---
const platform = new AppPlatform(`app-${env}`, {
    environment: env,

    dbInstanceClass: dbClass,
    dbMultiAz: isProd,
    dbStorageEncrypted: isProd,
    dbAllocatedStorage: isProd ? 100 : 20,
    dbBackupRetentionDays: isProd ? 30 : 7,
    dbPassword,

    vpcId: vpc.vpcId,
    privateSubnetIds: vpc.privateSubnetIds,
    dbIngressCidrs: ["10.0.0.0/16"],

    replicaRegion,                                   // undefined in dev

    oidcProviderArn: cluster.core.oidcProvider!.arn,
    oidcProviderUrl: cluster.core.oidcProvider!.url,
    serviceAccountNamespace: "web",
    serviceAccountName: "web-app",

    tags,
});

// --- HTTPS exposure (AC #6): ALB on 443 with ACM cert ---
const cert = new aws.acm.Certificate(`app-${env}-cert`, {
    domainName: cfg.require("domainName"),
    validationMethod: "DNS",
    tags,
});

const alb = new awsx.lb.ApplicationLoadBalancer(`app-${env}-alb`, {
    subnetIds: isProd ? vpc.publicSubnetIds : vpc.privateSubnetIds,
    internal: !isProd,
    defaultTargetGroup: { port: 8080, protocol: "HTTP", vpcId: vpc.vpcId, targetType: "ip" },
    listener: {
        port: 443,
        protocol: "HTTPS",
        sslPolicy: "ELBSecurityPolicy-TLS13-1-2-2021-06",
        certificateArn: cert.arn,
    },
    tags,
});

export const kubeconfig       = pulumi.secret(cluster.kubeconfig);
export const bucketName       = platform.bucketName;
export const dbEndpoint       = platform.dbEndpoint;
export const serviceRoleArn   = platform.roleArn;
export const dbSecretArn      = platform.connectionSecretArn;
export const albDnsName       = alb.loadBalancer.dnsName;
```

