  aws:region: us-east-1
  canonical-app:nodeCount: "2"
  canonical-app:nodeInstanceType: t3.medium
  canonical-app:dbInstanceClass: db.t3.micro
  canonical-app:domainName: dev.app.example.com
  canonical-app:dbPassword:
    secure: AAABAK1r...   # `pulumi config set --secret dbPassword <value>`
